/* TNM World Wrestling Report: CMLL (Consejo Mundial de Lucha Libre).
   Everything the site shows for this promotion lives in this file. */

P.cmll = {"short": "CMLL", "name": "Consejo Mundial de Lucha Libre", "home": "Mexico City", "c": "var(--cmll)", "asOf": "1991-07-14", "status": "The Torneo de Tercias semifinals are set for 7/19: Santo, Volador & Dragón vs. Los Brazos, and Atlantis, Rayo & Azteca vs. the Guerreros, whose Chavo shoved Fuerza aside for the pin. In Guadalajara the Dinamitas pinned Konnan twice, twelve days before he puts the title up against Vampiro's hair.", "stat": ["$550,260", "July gate, 6 logged shows"], "titles": [["Mexican National Heavyweight", "Konnan", "Title vs. Vampiro's hair at Verano de Escándalo, 7/26."], ["Mexican National Light Heavyweight", "El Dandy", "Retained vs. Blue Panther 7/6. Panther wants a rematch."], ["Mexican National Tag Team", "Volador & El Hijo del Santo", "Won the vacant titles 7/5. Dandy pinned Volador 7/12. Retained vs. Estrada & Cruz 7/13."], ["CMLL World Trios", "To be crowned", "Torneo de Tercias final at Verano de Escándalo, 7/26."]], "factions": [["Los Infernales", "Satánico, MS-1 and now El Dandy, revealed as the third man 7/12. Eliminated from the Tercias."], ["Los Intocables", "Jaque Mate, Masakre and Pierroth Jr. 0–3 as a trio. Masakre has Octagón's attention."], ["Los Hermanos Dinamita", "Cien Caras, Máscara Año 2000 and Universo 2000. Caras says the title shot should be his."], ["Foreign rudos", "Vampiro Canadiense, Kamala and Black Magic."], ["Los Guerreros", "Eddie, Chavo and Fuerza Guerrera, with Chavo and Fuerza already arguing."], ["Los Brazos", "Brazo de Oro, Brazo de Plata and El Brazo."]], "stories": [["Vampiro Puts His Hair on the Line", "Vampiro pinned Blue Panther, then challenged Konnan: his hair against the National Heavyweight Title at Verano. Konnan said yes. Cien Caras wanted the shot himself and shoved Vampiro."], ["Torneo de Tercias", "Eight trios, first CMLL World Trios Championship. Semifinals 7/19 at Arena México: Santo, Volador & Dragón vs. Los Brazos, and Atlantis, Rayo & Azteca vs. the Guerreros. Final at Verano 7/26."], ["Dandy Joins the Infernales", "The Light Heavyweight Champion was the mystery partner and pinned tag champion Volador, but the Infernales went out of the tournament."], ["Octagón Arrives", "A new masked técnico made the save when Los Intocables jumped Ángel Azteca, and went face to face with Masakre."], ["Lightning Kid Debuts", "The young American lost to Art Barr 2–0 but won over Arena México."], ["Trouble for the Guerreros", "Chavo distracted the referee so Eddie could beat Brazo de Plata. Fuerza Guerrera didn't like it. On 7/13 Chavo shoved Fuerza aside to take the pin that put them in the semifinals."]], "earlier": ["cmll-yamada-debuts"], "desk": ["Contracts use a ×5 card multiplier: each contract number drops 1 for every 5 CMLL cards. 7 cards run through 7/14.", "Tercias semifinals 7/19: Santo, Volador & Dragón vs. Los Brazos; Atlantis, Rayo & Azteca vs. Los Guerreros.", "Off-plan 7/14: the Dinamitas beat Konnan, Atlantis & Rayo 2–1 (Caras and Universo pinned Konnan); the plan had Rayo winning at home. Chicana beat Panther by DQ; the plan had Panther with the Swastika.", "Off-plan 7/13: Volador & Santo vs. Estrada & Cruz ran as a title defense (sheet: non-title). Champions retained.", "Blue Panther is 0–3 in his last three going into the August Dandy rematch.", "Arena México capacity is 10,500 in TNM. 7/12 drew 10,000.", "Guests for Acapulco 7/17: Jushin Liger, The Blue Blazer, Mike Rotunda.", "Kevin Sullivan: talks with CMLL ongoing.", "Puebla 7/8 gate was in pesos and isn't in the July total."], "roster": [["Ángel Azteca", "2–1 · Tercias semifinalist. Saved by Octagón 7/12"], ["Apolo Dantes", "1–1"], ["Art Barr", "2–1 · Beat the Lightning Kid on his debut"], ["Atlantis", "4–1 · Tercias semifinalist"], ["Black Magic", "0–4 · Also All Star Wrestling (UK)"], ["Blue Panther", "2–4 · Owed a title shot at Dandy. Called him out 7/14"], ["Brazo De Oro", "2–2 · Los Brazos. Tercias semifinalist"], ["Brazo De Plata", "2–2 · Los Brazos. Tercias semifinalist"], ["Chavo Guerrero", "4–0 · Los Guerreros. Tercias semifinalist. Shoved Fuerza aside 7/13"], ["Cien Caras", "1–3 · Los Hermanos Dinamita. Wants Konnan. Pinned him 7/14"], ["Eddie Guerrero", "5–0 · Also USWA. Tercias semifinalist"], ["El Brazo", "2–1 · Los Brazos. Tercias semifinalist"], ["El Dandy", "1–2 · Light Heavyweight Champion. Joined Los Infernales"], ["El Hijo Del Santo", "4–0 · Tag Champion. Also USWA"], ["Espectro Jr", "0–2 · No-showed 7/5"], ["Felino", "2–0 · Teams with brother Negro Casas"], ["Fuerza Guerrera", "2–0 · Los Guerreros. Tercias semifinalist. Chavo took his pin 7/13"], ["Jaque Mate", "1–3 · Los Intocables"], ["Javier Cruz", "0–2"], ["Jerry Estrada", "0–2"], ["Kamala", "1–3 · Foreign rudo"], ["Konnan", "4–2 · National Heavyweight Champion"], ["La Diabólica", "1–1 · Ruda"], ["Lola González", "0–2"], ["Masakre", "0–4 · Los Intocables. Staredown with Octagón"], ["Máscara Año 2000", "1–2 · Los Hermanos Dinamita"], ["MS-1", "2–4 · Los Infernales"], ["Negro Casas", "3–0"], ["Octagón", "1–0 · Debuted 7/12 with a save. Masakre next"], ["Octagoncito", "Mini"], ["Pantera Sureña", "Ruda, not used yet"], ["Pierroth Jr", "0–5 · Los Intocables"], ["Rayo De Jalisco Jr", "4–2 · Tercias semifinalist"], ["Sangre Chicana", "1–0"], ["Satánico", "2–3 · Los Infernales"], ["Silver King", "1–1"], ["The Lightning Kid", "0–1 · Debuted 7/12. Also Power Pro"], ["Tony Arce", "0–1"], ["Toshiyo Yamada", "3–0 · Joshi, touring"], ["Ultimo Dragón", "2–2 · Tercias semifinalist"], ["Universo 2000", "1–2 · Los Hermanos Dinamita"], ["Vampiro Canadiense", "1–3 · Title vs. Hair at Verano"], ["Volador", "5–0 · Tag Champion. Tercias semifinalist"], ["Vulcano", "0–1"]], "departures": []};

E.push(...[{"d": "1991-07-05", "p": "cmll", "city": "Mexico City", "venue": "Arena México", "type": "Viernes Espectacular", "gate": "14,000 · $189,000", "rate": "**3/4", "link": "VIERNE-1", "m": [["Toshiyo Yamada vs. Ultimo Dragón (exhibition)", "Yamada 2–0", "***"], ["#1 contenders: Los Brazos vs. Los Intocables", "Los Brazos 2–0", "1/4*"], ["Vacant National Tag titles: Volador & El Hijo del Santo vs. Los Infernales", "Volador & Santo 2–0. New champions", "***1/2"], ["Chavo, Fuerza & Eddie Guerrero vs. Los Intocables", "Guerreros 2–0 (Fuerza both falls)", "**3/4"], ["Fight Without Honor, Mexican Death Match: Blue Panther vs. Kamala", "Panther, Swastika, 1:01:41", "**3/4"], ["Konnan, Atlantis & Rayo vs. Vampiro, Cien Caras & Universo 2000", "Konnan's team 2–0", "***"]], "n": ["La Diabólica confronted Yamada after her win.", "Vampiro and Cien Caras had to be separated."]}, {"d": "1991-07-06", "p": "cmll", "city": "Mexico City", "venue": "Arena Coliseo", "type": "Sábado de Lucha Libre", "gate": "3,800 · $41,040", "rate": "**1/2", "link": "ARENA_CO", "m": [["Toshiyo Yamada vs. La Diabólica", "Yamada 2–0", "**3/4"], ["Konnan, Rayo & Atlantis vs. Vampiro, Kamala & Black Magic", "Konnan's team by DQ", "*1/4"], ["National Light Heavyweight: El Dandy (c) vs. Blue Panther", "Dandy, Dandina cradle. Refused the handshake", "****1/4"], ["Los Infernales vs. Cien Caras & Máscara Año 2000", "Satánico, Nudo", "*1/2"], ["Eddie & Chavo Guerrero vs. Brazo de Oro & El Brazo", "Guerreros (Chavo moonsault)", "**3/4"]], "n": ["Brazo de Plata challenged Eddie for 7/12."]}, {"d": "1991-07-08", "p": "cmll", "city": "Puebla", "venue": "Arena Puebla", "type": "Monday in Puebla", "gate": "~4,200 · ~140,000 pesos", "rate": "**1/2", "link": "ARENA_PU", "m": [["Eddie, Chavo & Jaque Mate vs. Brazo de Oro, Brazo de Plata & Rayo", "Guerreros & Mate 2–0", "**"], ["Negro Casas vs. Black Magic", "Casas, Casita", "****1/2"], ["Art Barr vs. Ángel Azteca", "Barr, frog splash", "***1/4"], ["Ultimo Dragón, Volador & Blue Panther vs. El Dandy, MS-1 & Pierroth Jr.", "Dragón's team 2–0", "**3/4"], ["National Heavyweight: Konnan (c) vs. Vampiro", "Konnan by DQ", "*1/4"]]}, {"d": "1991-07-10", "p": "cmll", "city": "Naucalpan", "venue": "El Toreo", "type": "Lucha Libre en Naucalpan", "gate": "6,000 · $64,800", "rate": "***3/4", "link": "EL_TOREO", "m": [["Azteca, El Hijo del Santo & Negro Casas vs. Espectro Jr., Masakre & MS-1", "Santo's team 2–0", "***"], ["La Diabólica vs. Lola González", "Diabólica, Diabólica Spin", "***1/2"], ["Volador & Rayo vs. Silver King & Satánico", "Volador & Rayo 2–0", "**3/4"], ["Atlantis vs. Black Magic", "Atlantis", "***"], ["Konnan vs. Apolo Dantes", "Konnan, spinebuster", "****3/4"]], "n": ["CMLL's first show at El Toreo. Konnan says it's going regular."]}, {"d": "1991-07-12", "p": "cmll", "city": "Mexico City", "venue": "Arena México", "type": "Viernes Espectacular", "gate": "10,000 · $135,000", "rate": "***", "link": "VIERNES_", "m": [["Negro Casas & Felino vs. Jerry Estrada & Javier Cruz", "Casas & Felino 2–0", "***"], ["Art Barr vs. The Lightning Kid (Kid's debut)", "Barr 2–0 (frog splash, figure-four)", "***"], ["Tercias QF: Atlantis, Rayo & Azteca vs. Los Intocables", "Atlantis's team 2–0. Octagón debuts for the save", "*1/2"], ["Tercias QF: Santo, Volador & Ultimo Dragón vs. Satánico, MS-1 & El Dandy", "Santo's team 2–1. Dandy revealed, pinned Volador", "**3/4"], ["Eddie Guerrero vs. Brazo de Plata", "Eddie 2–0 after Chavo distracts the referee", "***3/4"], ["Vampiro & Kamala vs. Konnan & Blue Panther", "Vampiro pins Panther (neck snap)", "***1/4"]], "n": ["Vampiro challenged Konnan: Title vs. Hair at Verano. Konnan accepted.", "Cien Caras protested and shoved Vampiro.", "Arena México: 10,000 of 10,500."]}, {"d": "1991-07-13", "p": "cmll", "city": "Mexico City", "venue": "Arena Coliseo", "type": "Sábado de Lucha Libre", "m": [["Octagón vs. Espectro Jr. (lightning match)", "Octagón (Octaclutch), 11:51. Masakre watches", "****1/4"], ["National Tag: Volador & El Hijo del Santo vs. Jerry Estrada & Javier Cruz", "Santo makes Cruz submit (camel clutch), 13:38. Champions retain", "****"], ["Satánico & MS-1 vs. Blue Panther & Ultimo Dragón", "Satánico pins Panther (rolling fallaway slam), 9:37. Dandy runs in; Panther and Dandy pulled apart", "***3/4"], ["Tercias QF D: Los Brazos vs. Cien Caras, Máscara Año 2000 & Universo 2000", "Plata pins Universo (Porky Plancha), 16:06. Caras blames Vampiro", "*"], ["Tercias QF C: Los Guerreros (Chavo, Eddie & Fuerza) vs. Kamala, Black Magic & Art Barr", "Chavo pins Black Magic (wheelbarrow stunner), 21:40. Chavo pushes Fuerza aside for the pin", "***"]], "ran": 1, "gate": "4,000 · $43,200", "rate": "**3/4", "n": ["Tercias semifinals (7/19): Santo, Volador & Dragón vs. Los Brazos; Atlantis, Rayo & Azteca vs. Los Guerreros.", "The sheet had the tag match as non-title; the sim ran it as a title defense, so Volador & Santo are recorded as retaining."]}, {"d": "1991-07-14", "p": "cmll", "city": "Guadalajara", "venue": "Arena Coliseo Guadalajara", "type": "Lucha Libre en Domingo", "m": [["Felino & Silver King vs. Tony Arce & Vulcano", "Felino & Silver King 2–0 (Felino takes both falls)", "**1/2"], ["Toshiyo Yamada vs. Lola González (lightning match)", "Yamada (reverse Gory special bomb), 10:05. Handshake after", "***3/4"], ["Apolo Dantes vs. Pierroth Jr.", "Dantes (victory roll), 12:36", "*3/4"], ["Sangre Chicana vs. Blue Panther", "Chicana by DQ, 4:37. Panther calls out El Dandy", "*1/2"], ["Hermanos Dinamita (Cien Caras & Máscara Año 2000) & Universo 2000 vs. Konnan, Atlantis & Rayo de Jalisco Jr.", "Dinamitas 2–1. Rayo takes fall 1; Caras, then Universo pin Konnan, 32:31", "****1/4"]], "ran": 1, "gate": "6,500 · $77,220", "rate": "**3/4", "n": ["Finish change: the plan had Rayo winning the deciding fall at home. The Dinamitas won 2–1 and pinned Konnan twice.", "Finish change: the plan had Panther winning with the Swastika. Chicana won by DQ."]}, {"d": "1991-07-17", "p": "cmll", "city": "Acapulco", "venue": "Coliseo Acapulco", "type": "Acapulco debut", "m": [["Tony Arce vs. Vulcano", "", ""], ["La Diabólica vs. Lola González", "", ""], ["Negro Casas & Felino vs. Art Barr & Jerry Estrada", "", ""], ["Atlantis vs. Mike Rotunda", "", ""], ["Jushin Liger & The Blue Blazer vs. Ultimo Dragón & The Lightning Kid", "", ""], ["Konnan vs. Cien Caras (non-title)", "", ""]], "n": ["Guests: Liger (WCW/NJPW), the Blazer and Rotunda (WWF/NJPW)."]}, {"d": "1991-07-19", "p": "cmll", "city": "Mexico City", "venue": "Arena México", "type": "Viernes Espectacular", "m": [["Torneo de Tercias semifinals", "", ""]]}, {"d": "1991-07-20", "p": "cmll", "city": "Mexico City", "venue": "Arena Coliseo", "type": "Women's division featured"}, {"d": "1991-07-21", "p": "cmll", "city": "Puebla", "venue": "Arena Puebla", "type": "Mask-vs-mask tease"}, {"d": "1991-07-26", "p": "cmll", "city": "Mexico City", "venue": "Arena México", "type": "Verano de Escándalo", "big": 1, "m": [["National Heavyweight Title vs. Hair: Konnan (c) vs. Vampiro Canadiense", "", ""], ["Torneo de Tercias final: first CMLL World Trios Champions", "", ""]]}, {"d": "1991-07-27", "p": "cmll", "city": "Mexico City", "venue": "Arena Coliseo", "type": "Verano fallout"}, {"d": "1991-07-28", "p": "cmll", "city": "Nezahualcóyotl", "venue": "Arena Neza", "type": "Fan appreciation"}, {"d": "1991-08-24", "p": "cmll", "city": "Mexico City", "venue": "Arena México", "type": "International Gran Prix", "big": 1, "m": [["Team Mexico vs. Team International, 10-man elimination", "", ""]]}]);

Object.assign(ARTICLES, {"cmll-mexico-calling": {"p": "cmll", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Mexico Report", "kicker": "CMLL · Backstage", "title": "Mexico Calling", "dek": "Eddie Guerrero and El Hijo del Santo both debuted in the USWA this month. Both are already spending most of their time in Mexico City.", "body": [["p", "The USWA made a lot of noise about El Hijo del Santo at Star Wars, where he beat Scott Taylor in an 18-minute match that was one of the best things on the show. Eddie Guerrero stole the Jonesboro TV taping two nights later. Both look like exactly the kind of talent Memphis has been missing."], ["p", "The problem is that both are under contract to CMLL, and CMLL is getting most of their dates. Santo is one half of the Mexican National Tag Team Champions and is in the Torneo de Tercias semifinals. Eddie is 4–0 in CMLL, in the middle of the Guerreros vs. Brazos feud and booked on almost every big show through Verano de Escándalo on July 26. Neither is on the USWA's plan for the rest of July."], ["h", "The numbers"], ["p", "Eddie is down to seven cards on his USWA deal and Santo to fourteen. If nothing changes, both could be finished in Memphis before the fall without ever getting a real program. The smart move for the USWA would be to book them as special attractions on the big Saturday shows rather than burn dates on TV. For now, Mexico has them."]], "facts": [["Eddie Guerrero", "4–0 in CMLL. 7 USWA cards left"], ["El Hijo del Santo", "CMLL tag champion. 14 USWA cards left"], ["USWA debuts", "Santo at Star Wars 7/1; Eddie's Jonesboro win 7/3"], ["CMLL priority", "Torneo de Tercias, Verano 7/26"]], "factTitle": "Two Contracts"}, "cmll-the-ceiling": {"p": "cmll", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Mexico Report", "kicker": "CMLL · Business", "title": "The 10,500 Ceiling", "dek": "Arena México holds 10,500, and CMLL is already close to filling it on Fridays. The only way left to grow the gate is the ticket price.", "body": [["p", "CMLL drew 10,000 to Arena México on July 12 for $135,000. The building holds 10,500. That means the Friday show is running at about 95 percent of capacity, and the promotion's best weekly gate can only go up another $6,750 at the current $13.50 average."], ["p", "That's a good problem to have. It also explains why the office is talking about pricing Verano de Escándalo at $16.20, the supercard rate. A sellout at that price would be $170,100, the biggest gate CMLL has had this summer, without needing a single extra fan."], ["h", "The rest of the loop"], ["p", "The other buildings are a different story. Arena Coliseo is drawing around 4,000 at $10.80. Puebla did around 4,200 on a Monday. The new Wednesday date at El Toreo opened with 6,000 and $64,800, and the office expects that number to drop once school is back and the novelty wears off. Acapulco opens on July 17 with Jushin Liger and the Blue Blazer as the draw."], ["p", "If CMLL wants more money, it will have to come from more dates, higher prices on the big shows, or a bigger building for the true supercards. The talk of a stadium show for the anniversary in September is starting to make sense."]], "facts": [["Arena México capacity", "10,500"], ["7/12 crowd", "10,000 · $135,000"], ["Room left", "500 seats"], ["Verano sellout", "$170,100 at $16.20"], ["El Toreo debut", "6,000 · $64,800"]], "factTitle": "The Numbers"}, "cmll-hair-on-the-line": {"p": "cmll", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Mexico Report", "kicker": "CMLL · Viernes Espectacular · Arena México, July 12", "title": "Vampiro Puts His Hair on the Line", "dek": "Vampiro pinned Blue Panther and then put his hair up against Konnan's title for Verano de Escándalo. Plus the Torneo de Tercias, Dandy's surprise, Octagón, and why Kevin Sullivan wasn't in the building.", "body": [["p", "CMLL drew 10,000 to Arena México on July 12, just short of the 10,500 the building holds, for the first night of the Torneo de Tercias, which will crown the promotion's first World Trios Champions at the Verano de Escándalo supercard on July 26. The gate was $135,000 and the card rated ***."], ["h", "Title vs. hair"], ["p", "The big angle came after the main event. Vampiro and Kamala beat Konnan and Blue Panther when Vampiro pinned Panther with a neck snap, which was the first loss of the summer for a team with Konnan on it. Vampiro then grabbed a pair of scissors and the microphone and challenged Konnan to put the Mexican National Heavyweight Title up against his hair at Verano. Konnan accepted on the spot. Cien Caras came down to argue that the shot should be his, and he and Vampiro got into a shoving match that took the locker room to break up. Caras and Vampiro have been at odds since their miscue on July 5, so that's a thread with somewhere to go after Verano."], ["h", "The tournament"], ["p", "Atlantis, Rayo de Jalisco Jr. and Ángel Azteca beat Los Intocables in straight falls, with Atlantis getting both pins. The match itself was weak at *1/2. What people will remember is what happened after: the Intocables jumped Azteca, and Octagón made his CMLL debut to clear the ring, then went face to face with Masakre. The second quarterfinal had the surprise of the night. Satánico and MS-1 came out without a partner, and the third man turned out to be El Dandy, the Light Heavyweight Champion. Dandy cradled Volador, one half of the tag champions, for the first fall, but Ultimo Dragón pinned Dandy with an inverted DDT and El Hijo del Santo submitted Satánico with the camel clutch, so the Infernales are out. Dandy's pin on Volador is the obvious next tag title program."], ["h", "The rest of the card"], ["p", "Eddie Guerrero vs. Brazo de Plata was the best match on the show at ***3/4. Eddie won in two straight falls with the frog splash, but the second fall came after Chavo got up on the apron and distracted the referee, and Fuerza Guerrera came out afterward to have words with Chavo. The Lightning Kid made his debut and lost to Art Barr in two falls, frog splash and then a figure-four, but he was well received and should get a run. Negro Casas and Felino opened the show by beating Jerry Estrada and Javier Cruz, with Casas taking both falls."], ["h", "Liger and the Blazer"], ["p", "Jushin Liger and The Blue Blazer are booked for CMLL's first show in Acapulco on Wednesday, against Ultimo Dragón and The Lightning Kid. Liger's trip reportedly came together through the New Japan office, which wants him working with Mexican juniors before a possible late-tour return and is said to be eyeing Ultimo Dragón for future junior tours. The Blazer, who everyone knows is Owen Hart, is using the WWF's three days off between WrestleFest and the July 18 Richfield TV taping to work under the hood. One source said Owen has been frustrated at being booked as \"the little brother\" in the Heenan angle and jumped at the chance to work a faster style again. The WWF office is said to be less than thrilled about him flying out of Mexico on the morning of a TV taping. Mike Rotunda is also on the show, against Atlantis."], ["h", "Where was Sullivan?"], ["p", "Kevin Sullivan, who hasn't been seen on WCW television since Columbus, was strongly rumored to be at Arena México on Friday, and several Mexican magazines went to press saying he'd be there. He never showed. According to people close to the situation, Sullivan flew into Mexico City midweek to meet with the CMLL office about working the International Gran Prix in August and possibly helping with the foreign talent. The meetings ran long and the two sides couldn't agree on dates, so CMLL chose not to advertise him until a deal was done rather than risk another no-show like Espectro Jr.'s on July 5. Negotiations with CMLL are said to be ongoing. With Cactus Jack now running the Dark Circle, there's plenty of speculation that Sullivan is headed south for an extended run, but nothing has been signed."]], "facts": [["Attendance", "10,000 (capacity 10,500)"], ["Gate", "$135,000"], ["Card", "***"], ["Best match", "Eddie vs. Brazo de Plata, ***3/4"], ["Set for Verano", "Konnan (c) vs. Vampiro, Title vs. Hair"], ["Tercias semifinalists", "Atlantis/Rayo/Azteca, Santo/Volador/Dragón"], ["Debuts", "Octagón, The Lightning Kid"], ["Next", "Arena Coliseo, Saturday 7/13"]], "factTitle": "Viernes Espectacular"}, "cmll-observer-notes-0712": {"p": "cmll", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-13", "region": "Mexico Report", "kicker": "CMLL · Backstage Notes", "title": "Backstage Notes: Arena México", "dek": "Liger and the Blue Blazer are coming to Acapulco, and Kevin Sullivan is talking to the CMLL office.", "factTitle": "Filed from", "facts": [["Show", "Viernes Espectacular, 7/12"], ["Gate", "10,000 · $135,000"], ["Card", "***"]], "body": [["h", "Arena México"], ["p", "Jushin Liger and the Blue Blazer are booked for Acapulco on 7/17. New Japan's office arranged Liger's date, and Owen Hart is using the WWF's days off."], ["h", "Arena México"], ["p", "Kevin Sullivan was rumored for Arena México but didn't appear. He met with the CMLL office about International Gran Prix dates, and negotiations are ongoing."]]}, "cmll-yamada-debuts": {"p": "cmll", "news": 1, "by": "Newsletter staff", "date": "1991-07-09", "region": "Mexico Report", "kicker": "CMLL · Arena Puebla", "title": "Yamada Debuts", "dek": "Toshiyo Yamada, one of the hardest-hitting women in Japanese wrestling, made her CMLL debut in Puebla. It's a small show and a big signal.", "body": [["p", "Toshiyo Yamada made her CMLL debut in a trios match at Arena Puebla this week. It wasn't an Arena México show and it wasn't in a main event, but it's the start of one of the more interesting experiments in Mexico this summer: a joshi star on an interpromotional tour, working against Mexican women in front of crowds that haven't seen her style before."], ["p", "Yamada is a stiff, aggressive worker from the All Japan Women's system, and the trios was booked as a showcase. The point was to let the crowd see what she does. By most accounts it worked."], ["h", "Why it matters"], ["p", "CMLL's women's division has been an afterthought for a while. The idea floating around is to build Yamada as a foreign challenger, which is a story Mexican crowds love, and eventually put her in with whoever holds the Women's Title. Irma González is the name being mentioned. A foreign invader working toward a title shot gives the division a reason to exist on the big Friday shows."], ["p", "The other name to watch is La Diabólica, who is exactly the kind of theatrical ruda who would make a good first opponent. If CMLL wants a big match out of this before the end of the summer, those two are it."], ["h", "The bigger picture"], ["p", "Yamada is one of several outsiders in CMLL right now. Kamala, Vampiro and Black Magic are doing the foreign heel act on the men's side, and Ultimo Dragón is training in Mexico. Arena México is drawing 14,000 to 16,000 a week. If the women's division can get even a piece of that audience to care, the experiment pays for itself."]], "facts": [["Debut", "Trios, Arena Puebla"], ["Style", "Joshi, interpromotional tour"], ["Possible title", "CMLL Women's (Irma González)"], ["Possible rival", "La Diabólica"], ["Arena México", "14,000–16,000 weekly"]], "factTitle": "The Debut"}, "cmll-chavo-pushes-fuerza": {"p": "cmll", "kicker": "CMLL · Sábado de Lucha Libre · Arena Coliseo, July 13", "title": "Chavo Takes the Pin", "dek": "The Guerreros and Los Brazos reach the Tercias semifinals, Chavo shoves Fuerza out of the way, Octagón makes Espectro Jr. give up, and El Dandy can't stay away from Blue Panther.", "by": "By the magazine staff", "date": "1991-07-13", "factTitle": "The Card", "facts": [["Main", "Guerreros d. Kamala, Black Magic & Barr"], ["Semi", "Los Brazos d. Hermanos Dinamita"], ["Best match", "Octagón d. Espectro Jr., ****1/4"], ["Tercias semifinals 7/19", "Santo/Volador/Dragón vs. Brazos; Atlantis/Rayo/Azteca vs. Guerreros"]], "body": [["h", "Chavo Takes the Pin"], ["p", "The Torneo de Tercias filled out its semifinals at Arena Coliseo on Saturday night, and the Guerrero family is through. Whether the family is still together is another question."], ["p", "Eddie, Chavo and Fuerza Guerrera went more than twenty-one minutes with Kamala, Black Magic and Art Barr in the main event. Late in the match Fuerza had Black Magic set up and went for the cover. Chavo shoved him aside, hooked Black Magic for the wheelbarrow stunner and took the pin himself. Fuerza stared at him all the way to the back. Eddie walked between them."], ["p", "Los Brazos are the other semifinalists from Saturday. Brazo de Oro, Brazo de Plata and El Brazo beat Cien Caras, Máscara Año 2000 and Universo 2000 when Plata flattened Universo with the Porky Plancha. Cien Caras didn't blame his brothers. He blamed Vampiro, who has had Caras's attention since he took the title shot Caras wanted."], ["p", "That sets the semifinals for Arena México on Friday: El Hijo del Santo, Volador and Ultimo Dragón against Los Brazos, and Atlantis, Rayo de Jalisco Jr. and Ángel Azteca against the Guerreros."], ["p", "Octagón had his first singles match in CMLL and made Espectro Jr. submit to the Octaclutch at 11:51 of a lightning match. The crowd was standing for the last three minutes. Masakre watched the whole thing from the entrance and didn't come any closer."], ["p", "Volador and El Hijo del Santo kept the Mexican National Tag Team Championship against Jerry Estrada and Javier Cruz. Santo took the deciding fall when he bent Cruz back in the camel clutch at 13:38."], ["p", "Satánico and MS-1 beat Blue Panther and Ultimo Dragón when Satánico caught Panther with a rolling fallaway slam. El Dandy, the third Infernal, ran in during the match and went straight for Panther. It took referees and half the locker room to pull them apart."]]}, "cmll-observer-coliseo-0713": {"p": "cmll", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-13", "region": "Mexico Report", "kicker": "CMLL · Mexico City · 7/13", "title": "Observer: Arena Coliseo", "dek": "Octagón vs. Espectro Jr. goes ****1/4, the tag title match goes ****, and the Guerrero split takes its next step.", "factTitle": "Match observations", "facts": [["Show", "Sábado de Lucha Libre, 7/13"], ["Venue", "Arena Coliseo"], ["Attendance", "4,000 (capacity 5,000)"], ["Gate", "$43,200"], ["Average ticket", "$10.80"], ["Card", "**3/4"], ["Match of the night", "Octagón d. Espectro Jr., ****1/4"]], "body": [["p", "The Saturday Arena Coliseo show finished the Torneo de Tercias quarterfinals and came in at **3/4. The two quarterfinals were the weakest matches on the card, which is why the number isn't higher. Arena Coliseo drew 4,000 of its 5,000 seats at a $10.80 average for a $43,200 gate, a little better than the 3,800 for last Saturday's show."], ["p", "Octagón made Espectro Jr. submit to the Octaclutch in 11:51. ****1/4. Octagón's first singles match in the company and an outstanding one. They've given him a strong start: the save on Azteca on Friday and now a clean submission. Masakre was out to watch, which is the next program."], ["p", "Volador & El Hijo del Santo beat Jerry Estrada & Javier Cruz in 13:38 when Santo made Cruz submit to the camel clutch. ****. This was planned as a non-title match, but it was run as a title defense, so the champions are officially 1–0 in defenses. Santo is great, and Estrada and Cruz worked hard."], ["p", "Satánico & MS-1 beat Blue Panther & Ultimo Dragón when Satánico pinned Panther with a rolling fallaway slam in 9:37. ***3/4. Dandy ran in, and he and Panther had to be separated. Panther has now lost two straight, Friday's main event and this. He's the guy getting a title rematch with Dandy in August, so they'll need to turn that around."], ["p", "Los Brazos beat Cien Caras, Máscara Año 2000 & Universo 2000 when Brazo de Plata pinned Universo with the Porky Plancha in 16:06. *. Caras blamed Vampiro afterward, which keeps the Caras vs. Vampiro tension going on the rudo side heading into Verano."], ["p", "The Guerreros beat Kamala, Black Magic & Art Barr in 21:40 when Chavo pinned Black Magic after a wheelbarrow stunner. ***. Chavo shoved Fuerza aside to take the pin, the second straight show where Chavo and Fuerza have had words. The plan is Chavo vs. Fuerza on 7/20 with Eddie interfering, and Art Barr eventually ending up with Eddie and Chavo, so Barr being on the other side here doesn't hurt anything."], ["p", "Bottom line: two great matches and two slow quarterfinals. The semifinals are set for Friday at Arena México."]]}, "cmll-diary-chavo-0713": {"p": "cmll", "series": "diary", "by": "Chavo Guerrero", "date": "1991-07-13", "place": "Hotel Isabel, Centro, Mexico City", "kicker": "From the Road · Mexico City, 7/13", "title": "Family Business", "dek": "Chavo Guerrero takes the pin that Fuerza wanted and doesn't apologize for it.", "factTitle": "The Night", "facts": [["Show", "Sábado de Lucha Libre, Arena Coliseo"], ["Match", "Guerreros d. Kamala, Black Magic & Barr"], ["Finish", "Chavo pins Black Magic, 21:40"], ["Rating", "***"], ["Next", "Tercias semifinal, Arena México 7/19"]], "body": [["p", "Twenty-one minutes in July in Arena Coliseo. The building doesn't breathe. By the end I couldn't feel my hands."], ["p", "Fuerza had Black Magic set up and went for the cover, and I moved him. I didn't push him hard. I moved him the way you move a chair. Then I hooked Black Magic and put him on his head and counted along with the referee."], ["p", "Fuerza wanted to talk about it in the dressing room. I told him the same thing my father told me: in this family, the one who finishes the job gets paid. He's not family. He's a good luchador and he's been around a long time, and that's all he is."], ["p", "Eddie got between us. Eddie always gets between people. He'll figure out soon enough which side he's on."], ["p", "Kamala is something else in there. He doesn't sell anything, he doesn't speak, and the crowd is scared of him for real. Art Barr is the one I'd keep an eye on. He's a gringo, but he works like he was born here, and he's hungrier than anybody on the card. Eddie likes him. I'm starting to see why."], ["p", "Semifinal on Friday at Arena México against Atlantis, Rayo and Azteca. Three técnicos and ten thousand people who want to see them beat us. Good. I like it better when they hate us."]]}, "cmll-dinamitas-stun-guadalajara": {"p": "cmll", "kicker": "CMLL · Lucha Libre en Domingo · Guadalajara, July 14", "title": "The Dinamitas Silence Guadalajara", "dek": "Rayo wins the first fall at home, then Cien Caras and Universo 2000 pin Konnan twice. Blue Panther loses his temper and calls out El Dandy.", "by": "By the magazine staff", "date": "1991-07-14", "factTitle": "The Card", "facts": [["Main", "Hermanos Dinamita d. Konnan, Atlantis & Rayo, 2–1"], ["Best match", "The main event, ****1/4"], ["Also", "Yamada d. Lola González, ***3/4"], ["Next", "Acapulco, 7/17"]], "body": [["h", "The Dinamitas Silence Guadalajara"], ["p", "Rayo de Jalisco Jr. came home to Guadalajara on Sunday night and gave the Arena Coliseo the first fall it wanted. The rest of the night belonged to Los Hermanos Dinamita."], ["p", "Rayo, Atlantis and Konnan, the National Heavyweight Champion, faced Cien Caras, Máscara Año 2000 and Universo 2000 over two out of three falls. At 12:39 Rayo locked Máscara Año 2000 in the Cavernaria, and the building came apart. Then the Dinamitas went to work on Konnan. Cien Caras slammed the champion and pinned him to even the match, and after more than thirty minutes Universo 2000 came off the top with a flying bodypress and pinned Konnan again for the deciding fall."], ["p", "Cien Caras stood over Konnan with the belt held up in the air, the same Cien Caras who protested when Vampiro got the title shot he wanted. Konnan defends that title against Vampiro's hair at Verano de Escándalo on July 26. He meets Caras in Acapulco on Wednesday."], ["p", "Blue Panther's night was short and ugly. He had Sangre Chicana in trouble when he lost his head, refused the referee's warnings and was disqualified at 4:37. Afterward he grabbed the microphone, and it wasn't Chicana he wanted. It was El Dandy, the Light Heavyweight Champion who ran in on him in Mexico City the night before. Panther said he'll find Dandy anywhere they put him."], ["p", "Toshiyo Yamada beat Lola González in a lightning match with the reverse Gory special bomb at 10:05, and the two women shook hands afterward to a standing ovation. Apolo Dantes rolled up Pierroth Jr. at 12:36, and Felino and Silver King beat Tony Arce and Vulcano in two straight falls, Felino taking both."]]}, "cmll-observer-guadalajara-0714": {"p": "cmll", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-14", "region": "Mexico Report", "kicker": "CMLL · Guadalajara · 7/14", "title": "Observer: Guadalajara", "dek": "The main event goes ****1/4 but not the way it was planned: the Dinamitas pin Konnan twice. Blue Panther loses by DQ. Yamada and Lola González steal the undercard.", "factTitle": "Match observations", "facts": [["Show", "Lucha Libre en Domingo, 7/14"], ["Venue", "Arena Coliseo Guadalajara"], ["Attendance", "6,500 (capacity 8,500)"], ["Gate", "$77,220"], ["Average ticket", "$11.88"], ["Card", "**3/4"], ["Match of the night", "Dinamitas d. Konnan, Atlantis & Rayo, ****1/4"]], "body": [["p", "CMLL's Sunday show in Guadalajara rated **3/4, with a long, very good main event and a strong women's match. Arena Coliseo Guadalajara drew 6,500 of its 8,500 seats at an $11.88 average for $77,220, the best CMLL gate outside Arena México this month."], ["p", "The story is the main event, and it didn't go the way it was planned. The idea was Rayo de Jalisco Jr. winning the deciding fall in his hometown. Instead the Dinamitas won 2–1, and both of their falls were pins on Konnan: Cien Caras with a bodyslam at 19:17 and Universo 2000 with a flying bodypress at 32:31. Rayo got the first fall on Máscara Año 2000 with the Cavernaria at 12:39, so the home crowd got something. ****1/4. Excellent match."], ["p", "Konnan being pinned twice twelve days before he puts the title up against Vampiro's hair isn't ideal, but it does help one program. Cien Caras is the guy who wants Konnan next, and Konnan vs. Caras is the main event in Acapulco on Wednesday. Caras pinning him clean in a trios gives that match a reason to exist. It's also the second straight loss for Konnan's side, after Vampiro pinned Panther in Friday's main event at Arena México."], ["p", "Felino & Silver King beat Tony Arce & Vulcano 2–0, Felino taking both falls (a senton in 28 seconds, then the Splash Mountain). **1/2."], ["p", "Toshiyo Yamada pinned Lola González with the reverse Gory special bomb in 10:05 of a lightning match. ***3/4. Yamada continues to be one of the best things in the company. They shook hands afterward, which is the right call with Lola about to team with Yamada against La Diabólica and Pantera Sureña."], ["p", "Apolo Dantes pinned Pierroth Jr. with a victory roll in 12:36. *3/4. Dull."], ["p", "Sangre Chicana beat Blue Panther by DQ in 4:37. *1/2. Another change from the plan, which had Panther winning with the Swastika. It still worked as a story: Panther losing his temper and then calling out El Dandy on the microphone, one night after Dandy ran in on him. But Panther is now 0–3 in three nights going into a title rematch, and somebody will need to give him a big win before August."], ["p", "Bottom line: a good show with the wrong guys going over in the main event, at least according to the sheet. Acapulco on Wednesday has Konnan vs. Caras and Liger, the Blue Blazer and Mike Rotunda as guests."]]}, "cmll-diary-rayo-0714": {"p": "cmll", "series": "diary", "by": "Rayo de Jalisco Jr.", "date": "1991-07-14", "place": "Home, Guadalajara", "kicker": "From the Road · Guadalajara, 7/14", "title": "One Fall at Home", "dek": "Rayo de Jalisco Jr. wins a fall in front of his family, loses the match, and goes home anyway.", "factTitle": "The Night", "facts": [["Show", "Lucha Libre en Domingo, Guadalajara"], ["Match", "Hermanos Dinamita d. Konnan, Atlantis & Rayo, 2–1"], ["His fall", "Cavernaria on Máscara Año 2000, 12:39"], ["Rating", "****1/4"]], "body": [["p", "I don't stay in a hotel in Guadalajara. My mother would never forgive me. I'm writing this at the kitchen table, and she has already fed me twice."], ["p", "My father wrestled in that building for thirty years. The people there still call me his son before they call me by my own name. That's fine. When I locked the Cavernaria on Máscara Año 2000 and he gave up, they were shouting for both of us."], ["p", "After that, the night was the Dinamitas'. Cien Caras doesn't need much. He picked Konnan up and slammed him like a sack of corn and sat on him for three. And at the end, after half an hour, Universo came off the top while I was on the floor with Máscara, and I heard the count from outside the ring. I didn't get back in time."], ["p", "Konnan said nothing in the dressing room. He's the champion and he has Vampiro's hair to think about. Atlantis told me we'll get them again. Atlantis always says the right thing."], ["p", "The kids outside the arena didn't care that we lost. They wanted to touch the mask. A little one asked me if I was going to be champion like my father. I told him yes. Then I came home and my mother asked me the same question, and I told her the same thing."], ["p", "Acapulco on Wednesday. Then Friday, the semifinal at Arena México against the Guerreros. That one I'm not losing."]]}});

CONTRACTS.cmll = {"basis": "Per show", "unit": "per appearance (house rate)", "revenue": "July so far: $550,260 from six logged shows. Arena México Fridays draw $135,000–$189,000; Arena Coliseo Saturdays $41,000–$43,200; Guadalajara $77,220; Naucalpan $64,800. Puebla was logged in pesos (~140,000).", "target": "Weekly payroll at or under 35% of that week's gate.", "how": "Same formula as the USWA. Each appearance pays the base rate × the show multiplier. Arena México Fridays and supershows add a cut of the gate for the main event (usually the trios headliner) and semi-main, split evenly among the wrestlers in the match. Managers and announcers are on the same scale.", "classes": [["House show", "Puebla Sundays, Naucalpan, Acapulco, Sábado de Lucha Libre", "1×", "—", "—"], ["Arena México Friday", "Viernes Espectacular", "2×", "8% of gate", "4% of gate"], ["Supershow", "Verano de Escándalo, International Gran Prix", "3×", "10% of gate", "5% of gate"]], "rows": [["A", "Konnan", 900, "National Heavyweight Champion"], ["A", "Rayo De Jalisco Jr", 800, ""], ["A", "Atlantis", 700, ""], ["A", "Negro Casas", 700, ""], ["A", "Cien Caras", 700, ""], ["A", "El Dandy", 650, "National Light Heavyweight Champion"], ["A", "Vampiro Canadiense", 650, "Title vs. hair at Verano"], ["A", "Octagón", 650, "Debuted 7/12"], ["A", "Satánico", 600, "Los Infernales"], ["B", "El Hijo Del Santo", 550, "National Tag Champion, also USWA"], ["B", "Máscara Año 2000", 550, ""], ["B", "Universo 2000", 550, ""], ["B", "MS-1", 500, ""], ["B", "Ultimo Dragón", 500, ""], ["B", "Volador", 450, "National Tag Champion"], ["B", "Eddie Guerrero", 450, "Also USWA"], ["B", "Fuerza Guerrera", 450, ""], ["B", "Kamala", 450, ""], ["B", "Blue Panther", 450, ""], ["B", "Art Barr", 400, ""], ["B", "Toshiyo Yamada", 400, "Joshi, touring"], ["C", "Pierroth Jr", 350, ""], ["C", "Sangre Chicana", 350, ""], ["C", "Felino", 300, ""], ["C", "Chavo Guerrero", 300, ""], ["C", "Brazo De Oro", 300, ""], ["C", "Brazo De Plata", 300, ""], ["C", "El Brazo", 300, ""], ["C", "Silver King", 300, ""], ["C", "Jerry Estrada", 300, ""], ["C", "Javier Cruz", 250, ""], ["C", "Apolo Dantes", 250, ""], ["C", "Ángel Azteca", 250, ""], ["C", "Black Magic", 250, "Also ASW"], ["C", "The Lightning Kid", 250, "Also Power Pro"], ["C", "La Diabólica", 250, "Women's division"], ["C", "Pantera Sureña", 200, "Women's division"], ["D", "Masakre", 200, ""], ["D", "Jaque Mate", 200, ""], ["D", "Lola González", 200, "Women's division"], ["D", "Espectro Jr", 150, ""], ["D", "Vulcano", 150, ""], ["D", "Tony Arce", 150, ""], ["D", "Octagoncito", 150, "Mini"], ["O", "TBD: Arena México ring announcer", 60, "Name to be set"], ["O", "TBD: TV commentator", 60, "Name to be set"]], "total": 17870, "check": "A typical Arena México Friday (about 25 workers, ~$150K gate) pays about $34K: about 23%."};

